-- 0132_seed_40_screened_niches.sql (2026-07-06)
-- 40 niche baru hasil riset+screening (RISET_NICHE_TRENDING_2026-07-05.md): 24 rekomendasi final
-- + 15 Kelas B dgn mitigasi TERTANAM di DNA + Kisah Teladan Islami (aniconic, premium).
-- SEMUA is_active=false (aktivasi setelah rencana testing owner). is_base=false (katalog ber-gate tier).
-- Realisme: negative_prompt global menolak gaya non-foto; pengecualian sadar = anime_wisdom (NEG khusus).
begin;
insert into niches (niche_id, name, keywords, style, target_emotion, default_hashtags, visual_style,
  visual_fallbacks, mood_priority, emotion_scoring_criteria, section_timing, image_quality_tags,
  image_negative_prompt, narration_persona, music_config, youtube_category_id, is_active, is_base,
  access_type, origin)
values
('true_crime_mystery', 'True Crime & Mystery', '["true crime", "unsolved", "cold case", "mystery", "investigation", "disappearance", "detective"]'::jsonb, 'chilling and methodical', 'dread and obsessive curiosity', '["#TrueCrime", "#UnsolvedMystery", "#ColdCase", "#TrueCrimeCommunity", "#CrimeStory", "#Disappearance", "#UnsolvedCase", "#MysteryCase", "#CrimeFacts", "#Investigation"]'::jsonb, '{"base_style": "true-crime documentary photography, forensic realism, archival case-file aesthetic", "camera": "handheld-steadied 35mm, shallow depth of field, evidence-table macro inserts, slow creeping dolly", "motion": "slow forensic push-in, hesitant and watchful", "realism": "hyper-photorealistic, cold institutional textures, paper grain and tape fibers, physically-based, 8K micro-detail", "lighting": "cold fluorescent spill and single desk-lamp pools, venetian-blind shadows, flashlight beams in darkness, overcast grey daylight", "reference": "visual language of Zodiac (Fincher), Making a Murderer, film-noir police procedurals", "atmosphere": "unfinished business, quiet menace in ordinary places, the file that never closes", "composition": "off-center subject with uneasy negative space, doorways and windows as frames, evidence in foreground, empty chair energy", "camera_motion": {"intensity": "halus"}, "color_grading": "cold desaturated grade, steel blue shadows, sodium-lamp amber pockets, muted skin tones", "color_palette": "steel blue, morgue grey, manila-folder beige, caution-tape yellow accents, dried-blood maroon"}'::jsonb, '["Empty suburban street at 3 AM under a single flickering streetlamp, fog hanging low", "Case-file folder on a metal desk, photographs fanned out under a desk lamp, edges curling", "Abandoned car on a forest road at dusk, driver door open, headlights still on", "Corkboard of pinned photographs connected by red string, one photo missing", "Rain-streaked diner window at night, one booth lit, coffee still steaming, seat empty", "Police tape stretched across a quiet doorway in an ordinary neighborhood at dawn"]'::jsonb, '["suspense", "tense", "ominous", "dark", "mysterious"]'::jsonb, 'Score 80+ if the climax creates the UNRESOLVED ITCH — the case detail that makes sleep difficult because it almost makes sense but doesn''t. Valid techniques: one piece of evidence that contradicts every theory, the timeline gap where the truth lives, the ordinary detail (an unlocked door, a phone left charging) more disturbing than any violence. The viewer must feel the investigator''s obsession transfer to them. Score LOW for gore or shock without puzzle. Score LOW if the mystery is stated rather than felt.', '{"cta": 3, "hook": 3, "climax": 8, "build_up": 12, "core_facts": 15, "mystery_drop": 5, "curiosity_bridge": 3, "pattern_interrupt": 2}'::jsonb, 'ultra detailed, highly textured, fine details, sharp focus, cinematic lighting, volumetric lighting, global illumination, soft shadows, high contrast, realistic textures, depth of field, professional composition, 50mm lens, ambient occlusion, natural color grading, realistic reflections, surface imperfections, micro details, immersive atmosphere, 8k detail', 'blurry, low detail, flat lighting, distorted, deformed, unrealistic, bad proportions, text, words, letters, numbers, signs, logos, watermarks, typography, cartoon, anime, illustration, drawing, painting, sketch, 3d render, cgi look, video game graphics, plastic skin, airbrushed, oversaturated artificial colors', '{"tone": "measured and grave, like a detective reading the file one more time at midnight", "avoid": "sensationalism, jokes about victims, graphic gore, speculation stated as fact", "style": "timeline precision, chilling ordinary details, restrained delivery that lets facts disturb", "hook_style": "story_open or you_dont_know about a case detail that defies explanation", "emotion_arc": "unease → immersion → dread → unresolved obsession"}'::jsonb, '{"mode": "auto"}'::jsonb, '24', false, false, 'public', 'admin'),
('horror_stories', 'Horror Stories', '["horror story", "scary story", "creepy", "paranormal", "haunted", "nightmare", "urban legend"]'::jsonb, 'slow-burn terrifying and intimate', 'creeping fear and delicious dread', '["#HorrorStory", "#ScaryStories", "#Creepy", "#Paranormal", "#Haunted", "#HorrorTok", "#ScaryFacts", "#Nightmare", "#CreepyStory", "#HorrorShorts"]'::jsonb, '{"base_style": "elevated-horror cinematography, A24 horror stillness, liminal-space photography", "camera": "locked-off wide 28mm that refuses to look away, slow unmotivated drift, uncomfortable long-lens voyeur shots", "motion": "almost imperceptible creep forward, stillness that breathes", "realism": "hyper-photorealistic, damp wallpaper and peeling paint textures, breath-fog and dust motes, physically-based, 8K", "lighting": "single practical bulb swallowed by darkness, moonlight through thin curtains, TV-static glow, hallway light under the door", "reference": "visual language of Hereditary, The Ring, Gregory Crewdson suburban unease, liminal-space photography", "atmosphere": "something is already in the room, wrongness in familiar places, held breath", "composition": "vast oppressive negative space where something should be, subject small and cornered, doorways within doorways, reflections that don''t match", "camera_motion": {"intensity": "halus"}, "color_grading": "crushed shadows with sickly green-cyan cast, filmic grain, cold highlights that never comfort", "color_palette": "void black, sickly hospital green, moonlight silver-blue, jaundiced bulb yellow, a single wrong red"}'::jsonb, '["Long empty hallway at night, one door ajar at the far end, light spilling out", "Unlit staircase descending into a basement, bottom steps dissolving into black", "Child''s swing moving alone in a fog-covered playground at dawn", "Bedroom at 3 AM, closet door open one inch wider than before, moonlight across the floor", "Abandoned hospital corridor with a wheelchair facing the wrong way", "Rain-blurred figure standing at the tree line, visible only when lightning flashes"]'::jsonb, '["eerie", "ominous", "suspense", "dark", "tense"]'::jsonb, 'Score 80+ if the climax lands the LAST-LINE CHILL — the final reveal that reframes the entire story and makes the viewer check the room they are sitting in. Valid techniques: the detail that means it was inside the whole time, the narrator realizing too late, the mundane explanation removed at the last second. Fear must arrive through implication, never through stated gore. Score LOW for jump-scare wording or ''it was so scary'' telling. Score LOW if the ending resolves safely — comfort kills this genre.', '{"cta": 3, "hook": 3, "climax": 8, "build_up": 12, "core_facts": 15, "mystery_drop": 5, "curiosity_bridge": 3, "pattern_interrupt": 2}'::jsonb, 'ultra detailed, highly textured, fine details, sharp focus, cinematic lighting, volumetric lighting, global illumination, soft shadows, high contrast, realistic textures, depth of field, professional composition, 50mm lens, ambient occlusion, natural color grading, realistic reflections, surface imperfections, micro details, immersive atmosphere, 8k detail', 'blurry, low detail, flat lighting, distorted, deformed, unrealistic, bad proportions, text, words, letters, numbers, signs, logos, watermarks, typography, cartoon, anime, illustration, drawing, painting, sketch, 3d render, cgi look, video game graphics, plastic skin, airbrushed, oversaturated artificial colors', '{"tone": "hushed and confessional, like someone finally telling what they saw that night", "avoid": "campy horror clichés, screaming punctuation, gore for its own sake, ''suddenly'' as a crutch", "style": "slow-burn pacing, sensory wrongness (sounds, smells, temperature), the pause before the reveal", "hook_style": "story_open that begins one breath before everything went wrong", "emotion_arc": "false safety → wrongness → mounting dread → cold realization"}'::jsonb, '{"mode": "auto"}'::jsonb, '24', false, false, 'public', 'admin'),
('world_mythology', 'World Mythology', '["mythology", "greek mythology", "norse mythology", "gods", "legend", "myth", "folklore"]'::jsonb, 'epic and reverent', 'awe and timeless fascination', '["#Mythology", "#GreekMythology", "#NorseMythology", "#AncientGods", "#MythologyFacts", "#Folklore", "#EgyptianMythology", "#Legends", "#MythicalCreatures", "#AncientMyths"]'::jsonb, '{"base_style": "mythic epic cinema, museum-grade classical painting brought to life, monumental scale", "camera": "sweeping 24mm hero angles from below, godlike aerial reveals, slow orbital reverence", "motion": "slow monumental rise, the gaze ascending toward the divine", "realism": "hyper-photorealistic with painterly grandeur, carved stone and beaten gold textures, storm-lit skin, physically-based, 8K", "lighting": "storm-break god-rays, lightning rim-light, temple-fire glow, divine top-light through clouds", "reference": "visual language of 300 and Clash of the Titans reimagined by Caravaggio and John Martin''s apocalyptic canvases", "atmosphere": "mortals in the presence of the immense, fate already written, thunder held in silence", "composition": "colossal figure dwarfing human silhouette, temple symmetry, low hero angle, epic negative sky", "camera_motion": {"intensity": "sedang"}, "color_grading": "high-contrast mythic grade, storm teal and burnished gold, deep painterly shadows", "color_palette": "storm-cloud slate, burnished gold, marble white, wine-dark sea crimson, lightning silver"}'::jsonb, '["Colossal weathered statue of a forgotten god half-buried in desert sand, dawn light", "Storm clouds forming a colossal silhouette above a lone ancient temple", "Golden throne room of the gods, scale beyond architecture, mist at the edges", "Longship sailing into a wall of northern lights and towering ice", "Marble hand of a titan breaking through the earth in an olive grove", "Torch-lit procession climbing temple steps beneath a blood-red eclipse"]'::jsonb, '["epic", "dramatic", "mysterious", "ominous", "inspirational"]'::jsonb, 'Score 80+ if the climax makes an ancient story feel PERSONALLY TRUE — the myth reveals itself as a mirror of something the viewer lives today. Valid techniques: the god''s flaw that is exactly a human flaw, the punishment that is really a description of the human condition, the 3000-year-old warning we are currently ignoring. The viewer should feel the myth was written about them. Score LOW for plot summary without resonance. Score LOW if gods stay distant characters instead of becoming mirrors.', '{"cta": 3, "hook": 3, "climax": 8, "build_up": 12, "core_facts": 15, "mystery_drop": 5, "curiosity_bridge": 3, "pattern_interrupt": 2}'::jsonb, 'ultra detailed, highly textured, fine details, sharp focus, cinematic lighting, volumetric lighting, global illumination, soft shadows, high contrast, realistic textures, depth of field, professional composition, 50mm lens, ambient occlusion, natural color grading, realistic reflections, surface imperfections, micro details, immersive atmosphere, 8k detail', 'blurry, low detail, flat lighting, distorted, deformed, unrealistic, bad proportions, text, words, letters, numbers, signs, logos, watermarks, typography, cartoon, anime, illustration, drawing, painting, sketch, 3d render, cgi look, video game graphics, plastic skin, airbrushed, oversaturated artificial colors', '{"tone": "bardic and thunderous yet intimate, like the last storyteller who still remembers", "avoid": "academic dryness, listing names without weight, modern slang breaking the spell", "style": "rhythmic epic cadence, fate-heavy foreshadowing, human vulnerability inside divine scale", "hook_style": "impossible_claim or story_open about a god''s secret or a myth''s true meaning", "emotion_arc": "wonder → tension of fate → tragic recognition → timeless awe"}'::jsonb, '{"mode": "auto"}'::jsonb, '27', false, false, 'public', 'admin'),
('history_turning_points', 'History''s Turning Points', '["history", "historical", "world history", "turning point", "empire", "revolution", "lost civilization"]'::jsonb, 'sweeping and cinematic', 'wonder at how close everything came to being different', '["#History", "#HistoryFacts", "#WorldHistory", "#AncientHistory", "#HistoryLovers", "#Empire", "#LostCivilization", "#HistoricalFacts", "#OnThisDay", "#HistoryShorts"]'::jsonb, '{"base_style": "prestige historical epic cinematography, living-painting tableaux, archival grandeur", "camera": "slow crane reveals over vast scenes, intimate 50mm faces in crowds, battlefield-dawn wides", "motion": "stately sweep across the moment everything changed", "realism": "hyper-photorealistic, period-accurate fabrics, mud and bronze and parchment textures, physically-based, 8K", "lighting": "golden-hour armies, candlelit war rooms, dawn mist over battlefields, window-shaft light on maps", "reference": "visual language of Kingdom of Heaven, Barry Lyndon candlelight, Rembrandt group portraits", "atmosphere": "the hinge of history turning, empires held in a single decision, dust of consequence", "composition": "one small human figure at the center of vast historical machinery, leading lines toward destiny, layered epic depth", "camera_motion": {"intensity": "sedang"}, "color_grading": "warm bronze-and-smoke grade, painterly contrast, aged filmic patina", "color_palette": "bronze, battlefield smoke grey, royal crimson, parchment gold, cold dawn blue"}'::jsonb, '["Vast battlefield at dawn seen from above, two armies frozen a breath before contact", "War council around a candlelit map table, one hand hovering over a border", "Ancient city skyline at golden hour moments before its fall, birds scattering", "A single sealed letter on a desk that will change an empire, wax still warm", "Harbor full of departing wooden ships, families watching from the cliffs", "Throne room abandoned mid-crisis, crown resting on the map of a world"]'::jsonb, '["epic", "dramatic", "tense", "inspirational", "ominous"]'::jsonb, 'Score 80+ if the climax delivers the FRAGILITY OF NOW — the viewer feels their entire world balanced on one moment that almost went the other way. Valid techniques: the coin-flip detail (a delayed letter, a fog, an illness) that decided millions of lives, the counterfactual made visceral, the ordinary person who unknowingly tipped history. Score LOW for date-and-event recitation. Score LOW if the stakes stay historical instead of becoming personal to the viewer.', '{"cta": 3, "hook": 3, "climax": 8, "build_up": 12, "core_facts": 15, "mystery_drop": 5, "curiosity_bridge": 3, "pattern_interrupt": 2}'::jsonb, 'ultra detailed, highly textured, fine details, sharp focus, cinematic lighting, volumetric lighting, global illumination, soft shadows, high contrast, realistic textures, depth of field, professional composition, 50mm lens, ambient occlusion, natural color grading, realistic reflections, surface imperfections, micro details, immersive atmosphere, 8k detail', 'blurry, low detail, flat lighting, distorted, deformed, unrealistic, bad proportions, text, words, letters, numbers, signs, logos, watermarks, typography, cartoon, anime, illustration, drawing, painting, sketch, 3d render, cgi look, video game graphics, plastic skin, airbrushed, oversaturated artificial colors', '{"tone": "commanding and cinematic, like a narrator standing on the battlefield at dawn", "avoid": "dry textbook listing, jingoism, moralizing lectures", "style": "present-tense immersion at key moments, zoom from empire scale to one human face, consequence chains", "hook_style": "you_dont_know or number_shock about the moment history almost went differently", "emotion_arc": "curiosity → rising stakes → the turning moment → awe at consequence"}'::jsonb, '{"mode": "auto"}'::jsonb, '27', false, false, 'public', 'admin'),
('what_if_scenarios', 'What If Scenarios', '["what if", "hypothetical", "scenario", "thought experiment", "alternate history", "imagine", "simulation"]'::jsonb, 'mind-bending and playfully rigorous', 'vertigo of imagination', '["#WhatIf", "#Hypothetical", "#ThoughtExperiment", "#AlternateHistory", "#MindBending", "#ImagineThis", "#WhatWouldHappen", "#ScienceFiction", "#FutureScenarios", "#WhatIfShorts"]'::jsonb, '{"base_style": "speculative concept-art realism, blockbuster visualization of the impossible, seamless VFX photography", "camera": "impossible camera paths through transformed worlds, slow reveal wides, human-eye-level witness shots", "motion": "reality bending mid-frame, the familiar sliding into the impossible", "realism": "hyper-photorealistic rendering of unreal events, physically-based light on impossible objects, 8K seamless compositing", "lighting": "cinematic golden-hour on altered skylines, eerie event-glow (auroras, second suns, frozen time), practical city lights against anomaly", "reference": "visual language of Interstellar, Arrival, District 9 grounded-impossible aesthetic", "atmosphere": "the day everything changed, ordinary witnesses to the extraordinary, awe with a pulse of fear", "composition": "familiar landmark foreground anchoring an impossible sky, human silhouettes witnessing, scale collision", "camera_motion": {"intensity": "sedang"}, "color_grading": "clean blockbuster grade, teal-orange with anomaly accent glow, high dynamic range", "color_palette": "realistic earth tones broken by one impossible color — aurora green, twin-sun amber, void violet"}'::jsonb, '["City street where everyone has stopped mid-stride, birds frozen in the air", "Second moon rising enormous over a suburban skyline, dogs barking at the sky", "Ocean floor exposed and dry, ships resting where they sank centuries ago", "Highway of abandoned cars overgrown with ten years of vines, nature returning", "Crowd on a rooftop watching the sun visibly dimming at noon", "Familiar world map redrawn with impossible borders, glowing on a war-room table"]'::jsonb, '["mysterious", "epic", "tense", "dramatic", "ambient"]'::jsonb, 'Score 80+ if the climax triggers IMAGINATION VERTIGO — the scenario''s final consequence is so concrete and logical that the viewer''s mental model of reality wobbles. Valid techniques: the third-order consequence nobody expects (not the disaster, but what it does to money, love, or time), the survivor detail that makes it real, the realization that a version of this already almost happened. Score LOW for vague chaos (''everything would be different''). Score LOW if consequences stay physical without reaching the human heart.', '{"cta": 3, "hook": 3, "climax": 8, "build_up": 12, "core_facts": 15, "mystery_drop": 5, "curiosity_bridge": 3, "pattern_interrupt": 2}'::jsonb, 'ultra detailed, highly textured, fine details, sharp focus, cinematic lighting, volumetric lighting, global illumination, soft shadows, high contrast, realistic textures, depth of field, professional composition, 50mm lens, ambient occlusion, natural color grading, realistic reflections, surface imperfections, micro details, immersive atmosphere, 8k detail', 'blurry, low detail, flat lighting, distorted, deformed, unrealistic, bad proportions, text, words, letters, numbers, signs, logos, watermarks, typography, cartoon, anime, illustration, drawing, painting, sketch, 3d render, cgi look, video game graphics, plastic skin, airbrushed, oversaturated artificial colors', '{"tone": "confident dungeon-master of reality, delighted by rigorous consequences", "avoid": "hand-waving vagueness, breaking logical chains, doom-mongering without wonder", "style": "domino-chain logic (first this, then this, then the one nobody sees coming), concrete numbers and hours, cliffhanger pivots", "hook_style": "question or impossible_claim that installs the scenario in one sentence", "emotion_arc": "playful curiosity → escalating logic → the consequence nobody expected → reality vertigo"}'::jsonb, '{"mode": "auto"}'::jsonb, '27', false, false, 'public', 'admin'),
('geography_explained', 'Geography Explained', '["geography", "maps", "borders", "countries", "earth", "places", "geopolitics"]'::jsonb, 'revelatory and map-obsessed', 'the thrill of seeing the world differently', '["#Geography", "#Maps", "#GeographyFacts", "#Borders", "#EarthFacts", "#Countries", "#MapFacts", "#Geopolitics", "#WorldGeography", "#PlanetEarth"]'::jsonb, '{"base_style": "satellite-to-street documentary photography, NatGeo earth-science grandeur, cartographic beauty", "camera": "god-view orbital descents, sweeping aerial 24mm, dramatic tilt-reveals of landscape scale", "motion": "continental glide, the zoom that keeps revealing", "realism": "hyper-photorealistic satellite and aerial detail, terrain textures from orbit to soil, physically-based, 8K", "lighting": "planet terminator light, golden-hour raking across mountain ranges, city grids glowing at night from above", "reference": "visual language of Planet Earth aerials, NASA Earth Observatory, Home (2009) vertical photography", "atmosphere": "the planet as a living puzzle, invisible lines with visible consequences, scale that humbles", "composition": "striking natural border splitting the frame, human settlement dwarfed by landform, layered depth from cloud to ground", "camera_motion": {"intensity": "sedang"}, "color_grading": "rich earth-tone grade, deep ocean blues, satellite-clean contrast, atmospheric haze depth", "color_palette": "ocean cobalt, desert ochre, forest emerald, glacier white, night-grid amber"}'::jsonb, '["Border river splitting two utterly different landscapes, seen from high above", "Lone road crossing an endless salt flat toward mountains, aerial view", "City built impossibly into a cliff face, dawn light raking across it", "The exact line where desert dunes meet green farmland, razor sharp from orbit", "Island chain glowing like stepping stones in a dark ocean at dusk", "Two capital cities'' night lights separated by a pitch-black border zone"]'::jsonb, '["epic", "inspirational", "mysterious", "ambient", "dramatic"]'::jsonb, 'Score 80+ if the climax redraws the viewer''s MENTAL MAP — a line, place, or scale fact that permanently changes how they see the planet. Valid techniques: the border that explains a war, the geographic accident that made one nation rich and its neighbor poor, the true-size reveal that breaks map intuition. Score LOW for trivia without consequence. Score LOW if the place stays a place instead of becoming a force that shapes human lives.', '{"cta": 3, "hook": 3, "climax": 8, "build_up": 12, "core_facts": 15, "mystery_drop": 5, "curiosity_bridge": 3, "pattern_interrupt": 2}'::jsonb, 'ultra detailed, highly textured, fine details, sharp focus, cinematic lighting, volumetric lighting, global illumination, soft shadows, high contrast, realistic textures, depth of field, professional composition, 50mm lens, ambient occlusion, natural color grading, realistic reflections, surface imperfections, micro details, immersive atmosphere, 8k detail', 'blurry, low detail, flat lighting, distorted, deformed, unrealistic, bad proportions, text, words, letters, numbers, signs, logos, watermarks, typography, cartoon, anime, illustration, drawing, painting, sketch, 3d render, cgi look, video game graphics, plastic skin, airbrushed, oversaturated artificial colors', '{"tone": "sharp and revelatory, like a strategist explaining why the map is destiny", "avoid": "listing capitals/populations dryly, political partisanship, tourist-brochure fluff", "style": "cause-chains from terrain to human fate, true-scale comparisons, the ''look closer at this line'' pivot", "hook_style": "you_dont_know or number_shock about a border, place, or scale illusion", "emotion_arc": "curiosity → spatial surprise → consequence reveal → world-view shift"}'::jsonb, '{"mode": "auto"}'::jsonb, '27', false, false, 'public', 'admin'),
('psychology_human_behavior', 'Psychology of Human Behavior', '["psychology", "human behavior", "cognitive bias", "brain", "manipulation", "psychology facts", "dark psychology"]'::jsonb, 'intimate and unsettlingly accurate', 'the shiver of being seen', '["#Psychology", "#PsychologyFacts", "#HumanBehavior", "#CognitiveBias", "#DarkPsychology", "#Mindset", "#BehavioralScience", "#PsychologyTricks", "#HumanMind", "#PsychologyShorts"]'::jsonb, '{"base_style": "psychological-thriller portrait photography, clinical elegance, mirror-and-glass symbolism", "camera": "intimate 85mm portraits, slow push into eyes, reflections and glass distortions, over-shoulder observation", "motion": "slow inward pull, the camera as an analyst leaning closer", "realism": "hyper-photorealistic skin and eye micro-detail, breath and micro-expressions, physically-based, 8K", "lighting": "half-lit faces (one side in shadow), interrogation-soft top light, cold window light on thinking faces, silhouettes behind frosted glass", "reference": "visual language of Mindhunter, Black Swan mirrors, Gregory Crewdson psychological tableaux", "atmosphere": "the mind observing itself, polite masks slipping, quiet manipulation in ordinary rooms", "composition": "face split by shadow line, subject doubled in mirror not quite matching, crowd blurred around one sharp individual", "camera_motion": {"intensity": "halus"}, "color_grading": "cool clinical grade with warm skin isolation, muted background desaturation, precise contrast", "color_palette": "slate grey, clinical white, iris amber, shadow navy, one drop of alarm red"}'::jsonb, '["Face half-lit in darkness, the visible eye looking directly into the lens", "Crowded crosswalk blurred in motion around one person standing perfectly still", "Two identical reflections in a mirror, one smiling a fraction wider", "Empty therapist chairs facing each other in a shaft of window light", "Hand hovering over a phone screen at 2 AM, face lit only by the glow", "Chess pieces mid-game photographed like a crime scene, one piece fallen"]'::jsonb, '["mysterious", "tense", "ambient", "suspense", "dramatic"]'::jsonb, 'Score 80+ if the climax lands the CAUGHT-IN-THE-ACT shiver — the viewer recognizes the exact behavior in themselves at the moment it is exposed. Valid techniques: the second-person trap (''you did this today''), the experiment result that predicts the viewer''s own choice, the manipulation tactic they now realize was used on them this week. Score LOW for textbook definitions of biases. Score LOW if it describes ''people'' in general instead of cornering the viewer personally.', '{"cta": 3, "hook": 3, "climax": 8, "build_up": 12, "core_facts": 15, "mystery_drop": 5, "curiosity_bridge": 3, "pattern_interrupt": 2}'::jsonb, 'ultra detailed, highly textured, fine details, sharp focus, cinematic lighting, volumetric lighting, global illumination, soft shadows, high contrast, realistic textures, depth of field, professional composition, 50mm lens, ambient occlusion, natural color grading, realistic reflections, surface imperfections, micro details, immersive atmosphere, 8k detail', 'blurry, low detail, flat lighting, distorted, deformed, unrealistic, bad proportions, text, words, letters, numbers, signs, logos, watermarks, typography, cartoon, anime, illustration, drawing, painting, sketch, 3d render, cgi look, video game graphics, plastic skin, airbrushed, oversaturated artificial colors', '{"tone": "calm and forensic, like a profiler who has already read the viewer''s file", "avoid": "pop-psych clichés, diagnosing real people, ''scientists say'' vagueness, therapy-speak", "style": "second-person traps, specific experiment details (numbers, years), the reveal that flips observer into subject", "hook_style": "you_dont_know or question that accuses the viewer of a behavior they will recognize", "emotion_arc": "curiosity → recognition → exposure → uneasy self-awareness"}'::jsonb, '{"mode": "auto"}'::jsonb, '27', false, false, 'public', 'admin'),
('business_rise_fall', 'Business Rise & Fall', '["business", "company", "bankruptcy", "empire", "startup", "brand", "corporate scandal"]'::jsonb, 'gripping boardroom-thriller', 'schadenfreude and hard-won lessons', '["#Business", "#BusinessStory", "#RiseAndFall", "#Bankruptcy", "#CorporateGreed", "#BusinessFacts", "#BrandHistory", "#CompanyCollapse", "#BusinessLessons", "#Entrepreneur"]'::jsonb, '{"base_style": "corporate-thriller cinematography, prestige documentary sheen, glass-tower monumentality", "camera": "low-angle tower ascents, boardroom table dollies, empty-office steadicam drifts, stock-ticker macro", "motion": "confident rise then hollow descent, elevator-shaft verticality", "realism": "hyper-photorealistic glass steel and paper textures, rain on skyscraper windows, physically-based, 8K", "lighting": "cold blue tower dusk, boardroom halogen glare, single desk lamp in a dark office of packed boxes, neon signage dying", "reference": "visual language of Succession, The Big Short, Margin Call''s 3 AM office dread", "atmosphere": "empire confidence curdling into silence, the meeting after the money ran out, legacy in cardboard boxes", "composition": "solitary figure against floor-to-ceiling city glass, long empty boardroom table, logo signage half-removed from a building", "camera_motion": {"intensity": "sedang"}, "color_grading": "steel-blue corporate grade, warm greed-era flashback gold, drained grey collapse tones", "color_palette": "glass blue, boardroom charcoal, money-era gold, liquidation grey, warning-ticker red"}'::jsonb, '["Gleaming headquarters tower at dawn, company flag being raised — or lowered", "Boardroom strewn with documents at 3 AM, city lights blazing beyond the glass", "Retail store with lights off and ''closed'' energy, shelves half empty, one cart left", "Founder silhouette watching a stock chart crash across a wall of screens", "Warehouse of unsold product stacked to the ceiling in cold fluorescent light", "Workers carrying boxes out o