('fable_stories', 'Modern Fables', '["moral story", "fable", "life lesson", "wisdom story", "short story", "inspirational story", "parable"]'::jsonb, 'timeless warm storybook', 'the soft gut-punch of a lesson earned', '["#MoralStory", "#Fable", "#LifeLessons", "#WisdomStory", "#ShortStory", "#InspirationalStory", "#StoryTime", "#Parable", "#LifeLesson", "#MoralOfTheStory"]'::jsonb, '{"base_style": "cinematic live-action storybook realism, timeless village-and-road settings, prestige period-film photography", "camera": "gentle 40mm following travelers and craftsmen, firelit close-ups on decisive faces, dawn wides on winding roads", "motion": "unhurried journey pace, the road unrolling toward the lesson", "realism": "hyper-photorealistic with storybook warmth — homespun cloth, wooden tools, orchard light, weathered kind faces, physically-based, 8K", "lighting": "hearth-fire glow, orchard golden hour, lantern-lit village nights, soft overcast on humble work", "reference": "visual language of classic fable illustration (Bilibin, Rockwell warmth) rendered photoreal, The Green Mile''s gentle gravity", "atmosphere": "any village, any century — the timeless testing ground of character, kindness weighed against cleverness", "composition": "two figures at a moral crossroads, humble object as story pivot (a loaf, a coin, an axe), road forking through the frame", "camera_motion": {"intensity": "halus"}, "color_grading": "warm timeless grade, storybook golds and forest greens, soft filmic bloom", "color_palette": "hearth gold, homespun brown, orchard green, dusk lavender, humble linen cream"}'::jsonb, '["Traveler sharing bread with a stranger at a crossroads, evening gold", "Old craftsman teaching young hands at a workbench, lantern light", "Two doors in a village wall — one gilded, one plain — morning mist", "Farmer planting a tree whose shade he will never sit in, wide dawn", "Coin glinting in a beggar''s bowl beneath a rich man''s hesitating shadow", "Small boat helping anoth